"""Offline planning only; never activates compute, renews funding or qualifies costs."""
import json,math
from pathlib import Path
base=Path(__file__).resolve().parent
state=json.loads((base/'funding-state.json').read_text())
costs=json.loads((base/'cost-scenarios.json').read_text())
p=state['permit'];remaining=state['operations']['snapshot']['remainingMicros']
rows=[]
for c in costs['scenarios']:
 if c['monthlyRedeemedCredits']!=30000:continue
 credits={'improvise':10,'music-dna':20,'ai-dj':2}[c['product']]
 other=c['nonInfrastructureAllowancesMicros']+c['infrastructureMicros']
 capacity=c['targetBudgetMicros']-other
 rows.append({'product':c['product'],'creditsPerUnit':credits,'assumedMonthlyRedeemedCredits':30000,'targetUnitCostMicros':c['targetBudgetMicros'],'forecastNonProviderMicros':other,'providerBudgetPerUnitMicros':capacity,'minimumDeliveredUnitsPerFullyReservedSongCycle':math.ceil(p['cycleMicros']/capacity) if capacity>0 and c['product']!='ai-dj' else None,'minimumMonthlyCreditsAtPostedCostAndAllowances':c['minimumMonthlyRedeemedCreditsAtTheseAssumptions'],'throughputProven':False})
result={'status':'PASS funding preparation; PARTIAL measured sustainability','asOf':state['at'],'currentPermit':{'expiresAt':p['expiresAt'],'capUSD':p['capMicros']/1e6,'remainingUSD':remaining/1e6,'remainingFullCycles':remaining//p['cycleMicros'],'unusedTailUSD':(remaining%p['cycleMicros'])/1e6,'automaticRenewal':False},'actualCustomerEvidence':{'liveJobsSincePermitStart':state['liveJobsSincePermitStart'],'paidCreditLots':state['paidCredits'],'observedCustomerMargin':None},'planning':{'sharedInfrastructureUSDPerMonth':150,'support':'5% of purchases require 10 minutes at $30/hour, allocated across 150 credits','retentionMonthsForecast':60,'retentionPolicy':'Until account/content deletion; 60 months is an estimate, not automatic deletion','channelProceeds':'Existing conservative net credit floor; no hypothetical fee savings counted','fullCycleMicros':p['cycleMicros'],'rows':rows},'continuationProposal':{'approved':False,'maximumAdditionalUSD':10,'durationDays':7,'maximumNewCycles':13,'maxCycleUSD':.75,'sameL4EndpointAndImage':True,'automaticRenewal':False,'notBefore':'Current permit ends or is explicitly retired; never combine unused balances','condition':'Review actual customer usage, complete posted charges, support demand and 65% margin. Any renewal is a new bounded introductory allowance, not qualified sustainable economics. Without approval, allow shutdown and keep Creator renewals paused.'},'optimizationExperiment':{'approved':False,'maximumAdditionalUSD':1.50,'maximumCycles':2,'maximumSongRequests':2,'durationMinutesPerCycle':40,'maxCycleUSD':.75,'gpu':'one L4','baselineRequests':1,'candidateRequests':1,'retries':0,'publicCustomerPermitUsed':False,'preconditions':['CPU image verification passes','Exact candidate image digest and two-cycle permit are reviewed','Same consented input and seed; accepted audio recipe unchanged','Separate independent stop-only guardian and isolated credits','No output publication; account for complete cycle charges and failures'],'acceptance':['Compare actual output and owner listening if output differs','Record elapsed time and peak memory','Reconcile all provider charges; do not add duplicate job estimates','Keep disabled unless technical and cost checks pass'],'limitation':'Two observations compare the optimization; they cannot establish representative customer economics.'},'costQualificationEnabled':False,'newSpendingAuthorized':False}
(base/'funding-plan.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'status':result['status'],'remainingFullCycles':result['currentPermit']['remainingFullCycles'],'observedMargin':None,'newSpendingAuthorized':False}))
